function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var A={name:'Atlas Engine',version:'2.1',speed:'fast',cost:'$40'};var B={name:'Atlas Engine',version:'2.3',speed:'very fast',cost:'$55'};var merged={},conflicts=[];Object.keys(A).forEach(function(k){if(A[k]===B[k]){merged[k]=A[k];}else{conflicts.push({field:k,a:A[k],b:B[k],resolution:'kept both with source tags'});merged[k]=A[k]+' | '+B[k];}});return{fields:Object.keys(A).length,merged:merged,conflicts:conflicts.length,conflict_notes:conflicts,retained_disagreement:conflicts.length>0};}
var SEED = 88001;
console.log(JSON.stringify(demoRun(SEED), null, 1));

